 57	package com.marealta.service;
 58	
 59	import java.math.BigDecimal;
 60	import java.math.RoundingMode;
 61	import java.time.LocalDate;
 62	
 63	public class PricingService {
 64	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
 65	    private static final RoundingMode ROUNDING_MODE = RoundingMode.HALF_EVEN;
 66	
 67	    public static boolean isHighSeason(LocalDate date) {
 68	        int month = date.getMonthValue();
 69	        int day = date.getDayOfMonth();
 70	
 71	        // July
 72	        if (month == 7) return true;
 73	
 74	        // December 15 to February 28/29
 75	        if (month == 12 && day >= 15) return true;
 76	        if (month == 1) return true;
 77	        if (month == 2) return true;
 78	
 79	        return false;
 80	    }
 81	
 82	    public static BigDecimal getNightlyRate(BigDecimal baseRate, LocalDate date) {
 83	        if (isHighSeason(date)) {
 84	            return baseRate.multiply(HIGH_SEASON_MULTIPLIER).setScale(2, ROUNDING_MODE);
 85	        }
 86	        return baseRate;
 87	    }
 88	
 89	    public static BigDecimal roundMoney(BigDecimal value) {
 90	        return value.setScale(2, ROUNDING_MODE);
 91	    }
 92	
 93	    public static PricingResult calculatePrice(LocalDate checkIn, LocalDate checkOut,
 94	                                                BigDecimal baseNightlyRate, String ratePlan,
 95	                                                String companyCode) {
 96	        int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
 97	
 98	        if (ratePlan.equals("WEEKEND_PACKAGE")) {
 99	            return calculateWeekendPackage(checkIn, checkOut, baseNightlyRate);
100	        }
101	
102	        BigDecimal subtotal = BigDecimal.ZERO;
103	        for (int i = 0; i < nights; i++) {
104	            LocalDate currentDate = checkIn.plusDays(i);
105	            BigDecimal rate = getNightlyRate(baseNightlyRate, currentDate);
106	            subtotal = subtotal.add(rate);
107	        }
108	        subtotal = roundMoney(subtotal);
109	
110	        BigDecimal discount = BigDecimal.ZERO;
111	        if (ratePlan.equals("NON_REFUNDABLE")) {
112	            discount = subtotal.multiply(new BigDecimal("0.15"));
113	        } else if (ratePlan.equals("CORPORATE")) {
114	            BigDecimal discountRate = getCorporateDiscountRate(companyCode);
115	            discount = subtotal.multiply(discountRate);
116	        } else if (ratePlan.equals("LONG_STAY")) {
117	            discount = subtotal.multiply(new BigDecimal("0.10"));
118	        }
119	        discount = roundMoney(discount);
120	
121	        BigDecimal total = subtotal.subtract(discount);
122	        total = roundMoney(total);
123	
124	        return new PricingResult(nights, subtotal, discount, total);
125	    }
126	
127	    private static BigDecimal getCorporateDiscountRate(String companyCode) {
128	        return switch (companyCode) {
129	            case "TECNOSUL" -> new BigDecimal("0.12");
130	            case "AGROVALE" -> new BigDecimal("0.18");
131	            case "FARMAVIDA" -> new BigDecimal("0.25");
132	            default -> BigDecimal.ZERO;
133	        };
134	    }
135	
136	    private static PricingResult calculateWeekendPackage(LocalDate checkIn, LocalDate checkOut,
137	                                                          BigDecimal baseNightlyRate) {
138	        int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
139	
140	        BigDecimal packagePrice = switch (nights) {
141	            case 2 -> new BigDecimal("520.00");
142	            default -> new BigDecimal("820.00");
143	        };
144	
145	        // This will be determined by room type in the controller
146	        BigDecimal subtotal = packagePrice;
147	        BigDecimal discount = BigDecimal.ZERO;
148	        BigDecimal total = packagePrice;
149	
150	        return new PricingResult(nights, subtotal, discount, total);
151	    }
152	
153	    public static class PricingResult {
154	        public int nights;
155	        public BigDecimal subtotal;
156	        public BigDecimal discount;
157	        public BigDecimal total;
158	
159	        public PricingResult(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
160	            this.nights = nights;
161	            this.subtotal = subtotal;
162	            this.discount = discount;
163	            this.total = total;
164	        }
165	    }
166	}

