  1	package com.marealta.service;
  2	
  3	import com.marealta.database.Database;
  4	import com.marealta.domain.Reservation;
  5	import com.marealta.domain.Room;
  6	import java.math.BigDecimal;
  7	import java.sql.Connection;
  8	import java.sql.PreparedStatement;
  9	import java.sql.ResultSet;
 10	import java.sql.SQLException;
 11	import java.time.LocalDate;
 12	import java.util.ArrayList;
 13	import java.util.List;
 14	
 15	public class ReservationService {
 16	    public static Reservation create(int roomNumber, String guestName, String guestEmail,
 17	                                      String guestCpf, LocalDate checkIn, LocalDate checkOut,
 18	                                      int guests, String ratePlan, String companyCode) throws SQLException {
 19	        Room room = RoomService.getRoomByNumber(roomNumber);
 20	        if (room == null) {
 21	            throw new IllegalArgumentException("ROOM_NOT_FOUND");
 22	        }
 23	
 24	        validateReservation(roomNumber, checkIn, checkOut, guests, room.capacity, ratePlan, companyCode);
 25	
 26	        int roomId = RoomService.getRoomIdByNumber(roomNumber);
 27	        PricingService.PricingResult pricing = calculatePricing(checkIn, checkOut, room, ratePlan, companyCode);
 28	
 29	        String sql = """
 30	            INSERT INTO reservations (room_id, guest_name, guest_email, guest_cpf,
 31	                check_in, check_out, guests, rate_plan, company_code, nights,
 32	                subtotal, discount, total, status, amount_paid)
 33	            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
 34	            RETURNING id
 35	        """;
 36	
 37	        try (Connection conn = Database.getConnection();
 38	             PreparedStatement stmt = conn.prepareStatement(sql)) {
 39	            stmt.setInt(1, roomId);
 40	            stmt.setString(2, guestName);
 41	            stmt.setString(3, guestEmail);
 42	            stmt.setString(4, guestCpf);
 43	            stmt.setObject(5, checkIn);
 44	            stmt.setObject(6, checkOut);
 45	            stmt.setInt(7, guests);
 46	            stmt.setString(8, ratePlan);
 47	            stmt.setString(9, companyCode);
 48	            stmt.setInt(10, pricing.nights);
 49	            stmt.setBigDecimal(11, pricing.subtotal);
 50	            stmt.setBigDecimal(12, pricing.discount);
 51	            stmt.setBigDecimal(13, pricing.total);
 52	            stmt.setString(14, "PENDING");
 53	            stmt.setBigDecimal(15, BigDecimal.ZERO);
 54	
 55	            try (ResultSet rs = stmt.executeQuery()) {
 56	                rs.next();
 57	                int id = rs.getInt("id");
 58	                return getReservationById(id);
 59	            }
 60	        }
 61	    }
 62	
 63	    public static Reservation getReservationById(int id) throws SQLException {
 64	        String sql = """
 65	            SELECT r.id, r.room_id, rm.number, r.guest_name, r.guest_email, r.guest_cpf,
 66	                   r.check_in, r.check_out, r.guests, r.rate_plan, r.company_code,
 67	                   r.nights, r.subtotal, r.discount, r.total, r.status, r.amount_paid, r.refund
 68	            FROM reservations r
 69	            JOIN rooms rm ON r.room_id = rm.id
 70	            WHERE r.id = ?
 71	        """;
 72	
 73	        try (Connection conn = Database.getConnection();
 74	             PreparedStatement stmt = conn.prepareStatement(sql)) {
 75	            stmt.setInt(1, id);
 76	            try (ResultSet rs = stmt.executeQuery()) {
 77	                if (rs.next()) {
 78	                    return mapReservation(rs);
 79	                }
 80	            }
 81	        }
 82	        return null;
 83	    }
 84	
 85	    public static void confirm(int reservationId, BigDecimal amountPaid) throws SQLException {
 86	        String updateSql = "UPDATE reservations SET status = 'CONFIRMED', amount_paid = ? WHERE id = ? AND status = 'PENDING'";
 87	
 88	        try (Connection conn = Database.getConnection();
 89	             PreparedStatement stmt = conn.prepareStatement(updateSql)) {
 90	            stmt.setBigDecimal(1, amountPaid);
 91	            stmt.setInt(2, reservationId);
 92	            int updated = stmt.executeUpdate();
 93	            if (updated == 0) {
 94	                throw new IllegalStateException("OPERATION_NOT_ALLOWED");
 95	            }
 96	        }
 97	    }
 98	
 99	    public static void checkIn(int reservationId) throws SQLException {
100	        String updateSql = "UPDATE reservations SET status = 'CHECKED_IN' WHERE id = ? AND status = 'CONFIRMED'";
101	
102	        try (Connection conn = Database.getConnection();
103	             PreparedStatement stmt = conn.prepareStatement(updateSql)) {
104	            stmt.setInt(1, reservationId);
105	            int updated = stmt.executeUpdate();
106	            if (updated == 0) {
107	                throw new IllegalStateException("OPERATION_NOT_ALLOWED");
108	            }
109	        }
110	    }
111	
112	    public static void checkOut(int reservationId) throws SQLException {
113	        String updateSql = "UPDATE reservations SET status = 'CHECKED_OUT' WHERE id = ? AND status = 'CHECKED_IN'";
114	
115	        try (Connection conn = Database.getConnection();
116	             PreparedStatement stmt = conn.prepareStatement(updateSql)) {
117	            stmt.setInt(1, reservationId);
118	            int updated = stmt.executeUpdate();
119	            if (updated == 0) {
120	                throw new IllegalStateException("OPERATION_NOT_ALLOWED");
121	            }
122	        }
123	    }
124	
125	    public static void cancel(int reservationId, String ratePlan) throws SQLException {
126	        Reservation res = getReservationById(reservationId);
127	        if (res == null) {
128	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
129	        }
130	
131	        if (!res.status.equals("PENDING") && !res.status.equals("CONFIRMED")) {
132	            throw new IllegalStateException("OPERATION_NOT_ALLOWED");
133	        }
134	
135	        BigDecimal refund = calculateRefund(res);
136	        String updateSql = "UPDATE reservations SET status = 'CANCELLED', refund = ? WHERE id = ?";
137	
138	        try (Connection conn = Database.getConnection();
139	             PreparedStatement stmt = conn.prepareStatement(updateSql)) {
140	            stmt.setBigDecimal(1, refund);
141	            stmt.setInt(2, reservationId);
142	            stmt.executeUpdate();
143	        }
144	    }
145	
146	    public static List<Reservation> getReservationsByRoomAndDate(int roomNumber, LocalDate date) throws SQLException {
147	        String sql = """
148	            SELECT r.id, r.room_id, rm.number, r.guest_name, r.guest_email, r.guest_cpf,
149	                   r.check_in, r.check_out, r.guests, r.rate_plan, r.company_code,
150	                   r.nights, r.subtotal, r.discount, r.total, r.status, r.amount_paid, r.refund
151	            FROM reservations r
152	            JOIN rooms rm ON r.room_id = rm.id
153	            WHERE rm.number = ?
154	              AND r.check_in <= ? AND r.check_out > ?
155	              AND r.status IN ('CONFIRMED', 'CHECKED_IN', 'CHECKED_OUT')
156	        """;
157	
158	        List<Reservation> reservations = new ArrayList<>();
159	        try (Connection conn = Database.getConnection();
160	             PreparedStatement stmt = conn.prepareStatement(sql)) {
161	            stmt.setInt(1, roomNumber);
162	            stmt.setObject(2, date);
163	            stmt.setObject(3, date);
164	            try (ResultSet rs = stmt.executeQuery()) {
165	                while (rs.next()) {
166	                    reservations.add(mapReservation(rs));
167	                }
168	            }
169	        }
170	        return reservations;
171	    }
172	
173	    public static List<Reservation> getReservationsByRoomInDateRange(int roomNumber, LocalDate start, LocalDate end) throws SQLException {
174	        String sql = """
175	            SELECT r.id, r.room_id, rm.number, r.guest_name, r.guest_email, r.guest_cpf,
176	                   r.check_in, r.check_out, r.guests, r.rate_plan, r.company_code,
177	                   r.nights, r.subtotal, r.discount, r.total, r.status, r.amount_paid, r.refund
178	            FROM reservations r
179	            JOIN rooms rm ON r.room_id = rm.id
180	            WHERE rm.number = ?
181	              AND r.check_in < ? AND r.check_out > ?
182	              AND r.status != 'CANCELLED'
183	        """;
184	
185	        List<Reservation> reservations = new ArrayList<>();
186	        try (Connection conn = Database.getConnection();
187	             PreparedStatement stmt = conn.prepareStatement(sql)) {
188	            stmt.setInt(1, roomNumber);
189	            stmt.setObject(2, end);
190	            stmt.setObject(3, start);
191	            try (ResultSet rs = stmt.executeQuery()) {
192	                while (rs.next()) {
193	                    reservations.add(mapReservation(rs));
194	                }
195	            }
196	        }
197	        return reservations;
198	    }
199	
200	    private static void validateReservation(int roomNumber, LocalDate checkIn, LocalDate checkOut,
201	                                             int guests, int capacity, String ratePlan,
202	                                             String companyCode) throws SQLException {
203	        if (guests < 1) {
204	            throw new IllegalArgumentException("INVALID_REQUEST");
205	        }
206	        if (guests > capacity) {
207	            throw new IllegalArgumentException("CAPACITY_EXCEEDED");
208	        }
209	        if (checkOut.compareTo(checkIn) <= 0) {
210	            throw new IllegalArgumentException("INVALID_REQUEST");
211	        }
212	
213	        // Validate rate plan rules
214	        if (ratePlan.equals("CORPORATE")) {
215	            if (companyCode == null || (!companyCode.equals("TECNOSUL") &&
216	                !companyCode.equals("AGROVALE") && !companyCode.equals("FARMAVIDA"))) {
217	                throw new IllegalArgumentException("INVALID_REQUEST");
218	            }
219	        }
220	
221	        if (ratePlan.equals("WEEKEND_PACKAGE")) {
222	            validateWeekendPackage(checkIn, checkOut);
223	        }
224	
225	        if (ratePlan.equals("LONG_STAY")) {
226	            int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
227	            if (nights < 7) {
228	                throw new IllegalArgumentException("INVALID_REQUEST");
229	            }
230	        }
231	
232	        // Check room availability
233	        List<Reservation> conflicts = getReservationsByRoomInDateRange(roomNumber, checkIn, checkOut);
234	        if (!conflicts.isEmpty()) {
235	            throw new IllegalArgumentException("ROOM_UNAVAILABLE");
236	        }
237	    }
238	
239	    private static void validateWeekendPackage(LocalDate checkIn, LocalDate checkOut) {
240	        int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
241	        if (nights != 2) {
242	            throw new IllegalArgumentException("INVALID_REQUEST");
243	        }
244	
245	        java.time.DayOfWeek checkInDay = checkIn.getDayOfWeek();
246	        java.time.DayOfWeek checkOutDay = checkOut.getDayOfWeek();
247	
248	        if (checkInDay != java.time.DayOfWeek.FRIDAY || checkOutDay != java.time.DayOfWeek.SUNDAY) {
249	            throw new IllegalArgumentException("INVALID_REQUEST");
250	        }
251	    }
252	
253	    private static PricingService.PricingResult calculatePricing(LocalDate checkIn, LocalDate checkOut,
254	                                                                   Room room, String ratePlan,
255	                                                                   String companyCode) {
256	        if (ratePlan.equals("WEEKEND_PACKAGE")) {
257	            BigDecimal packagePrice = switch (room.type) {
258	                case "STANDARD" -> new BigDecimal("520.00");
259	                case "DELUXE" -> new BigDecimal("820.00");
260	                case "SUITE" -> new BigDecimal("1200.00");
261	                default -> BigDecimal.ZERO;
262	            };
263	            int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
264	            return new PricingService.PricingResult(nights, packagePrice, BigDecimal.ZERO, packagePrice);
265	        }
266	
267	        return PricingService.calculatePrice(checkIn, checkOut, room.nightlyRate, ratePlan, companyCode);
268	    }
269	
270	    private static BigDecimal calculateRefund(Reservation res) {
271	        switch (res.ratePlan) {
