242	            throw new IllegalArgumentException("INVALID_REQUEST");
243	        }
244	
245	        java.time.DayOfWeek checkInDay = checkIn.getDayOfWeek();
246	        java.time.DayOfWeek checkOutDay = checkOut.getDayOfWeek();
247	
248	        if (checkInDay != java.time.DayOfWeek.FRIDAY || checkOutDay != java.time.DayOfWeek.SUNDAY) {
249	            throw new IllegalArgumentException("INVALID_REQUEST");
250	        }
251	    }
