 46	public class RoomsSeeder {
 47	    public static void seedRooms(Connection conn) throws SQLException {
 48	        String sql = "INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES (?, ?, ?, ?) ON CONFLICT DO NOTHING";
 49	
 50	        try (PreparedStatement stmt = conn.prepareStatement(sql)) {
 51	            addRoom(stmt, 101, "STANDARD", 2, new BigDecimal("249.90"));
 52	            addRoom(stmt, 102, "STANDARD", 2, new BigDecimal("249.90"));
 53	            addRoom(stmt, 201, "DELUXE", 3, new BigDecimal("389.90"));
 54	            addRoom(stmt, 202, "DELUXE", 3, new BigDecimal("389.90"));
 55	            addRoom(stmt, 301, "SUITE", 4, new BigDecimal("579.90"));
 56	        }
 57	    }
 58	
 59	    private static void addRoom(PreparedStatement stmt, int number, String type, int capacity, BigDecimal rate) throws SQLException {
 60	        stmt.setInt(1, number);
 61	        stmt.setString(2, type);
 62	        stmt.setInt(3, capacity);
 63	        stmt.setBigDecimal(4, rate);
 64	        stmt.addBatch();
 65	        stmt.executeBatch();
 66	    }
