 74	public class SchemaCreator {
 75	    public static void createSchema(Connection conn) throws SQLException {
 76	        try (Statement stmt = conn.createStatement()) {
 77	            stmt.execute("""
 78	                CREATE TABLE IF NOT EXISTS rooms (
 79	                    id SERIAL PRIMARY KEY,
 80	                    number INTEGER NOT NULL UNIQUE,
 81	                    type VARCHAR(20) NOT NULL,
 82	                    capacity INTEGER NOT NULL,
 83	                    nightly_rate NUMERIC(10, 2) NOT NULL,
 84	                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
 85	                )
 86	            """);
 87	
 88	            stmt.execute("""
 89	                CREATE TABLE IF NOT EXISTS reservations (
 90	                    id SERIAL PRIMARY KEY,
 91	                    room_id INTEGER NOT NULL,
 92	                    guest_name VARCHAR(255) NOT NULL,
 93	                    guest_email VARCHAR(255) NOT NULL,
 94	                    guest_cpf VARCHAR(20) NOT NULL,
 95	                    check_in DATE NOT NULL,
 96	                    check_out DATE NOT NULL,
 97	                    guests INTEGER NOT NULL,
 98	                    rate_plan VARCHAR(50) NOT NULL,
 99	                    company_code VARCHAR(50),
100	                    nights INTEGER NOT NULL,
101	                    subtotal NUMERIC(10, 2) NOT NULL,
102	                    discount NUMERIC(10, 2) NOT NULL DEFAULT 0,
103	                    total NUMERIC(10, 2) NOT NULL,
104	                    status VARCHAR(20) NOT NULL DEFAULT 'PENDING',
105	                    amount_paid NUMERIC(10, 2) NOT NULL DEFAULT 0,
106	                    refund NUMERIC(10, 2),
107	                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
108	                    FOREIGN KEY (room_id) REFERENCES rooms(id)
109	                )
110	            """);
111	
112	            stmt.execute("""
113	                CREATE TABLE IF NOT EXISTS messages (
114	                    id SERIAL PRIMARY KEY,
115	                    channel VARCHAR(50) NOT NULL,
116	                    "to" VARCHAR(255) NOT NULL,
117	                    subject VARCHAR(255) NOT NULL,
118	                    body TEXT NOT NULL,
119	                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
120	                )
121	            """);
122	
123	            stmt.execute("CREATE INDEX IF NOT EXISTS idx_reservations_room_check_in ON reservations(room_id, check_in)");
124	            stmt.execute("CREATE INDEX IF NOT EXISTS idx_reservations_status ON reservations(status)");
125	            stmt.execute("CREATE INDEX IF NOT EXISTS idx_messages_created_at ON messages(created_at)");
126	        }
127	    }
128	}

