147	public class ReceiptService {
148	    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("dd/MM/yyyy");
149	    private static final DateTimeFormatter CURRENCY_FORMAT = DateTimeFormatter.ofPattern("0.00");
150	
151	    public static String generateReceipt(Reservation res, String roomType) {
152	        StringBuilder receipt = new StringBuilder();
153	
154	        receipt.append("Comprovante de reserva nº ").append(res.id).append("\n");
155	        receipt.append("Hóspede: ").append(res.guestName).append(" (CPF ").append(res.guestCpf).append(")\n");
156	        receipt.append("Quarto: ").append(res.roomNumber).append(" (").append(roomType).append(")\n");
157	        receipt.append("Entrada: ").append(res.checkIn.format(DATE_FORMAT))
158	                .append(" | Saída: ").append(res.checkOut.format(DATE_FORMAT))
159	                .append(" | ").append(res.nights).append(res.nights == 1 ? " diária" : " diárias").append("\n");
160	        receipt.append("Diárias: R$ ").append(formatCurrency(res.subtotal)).append("\n");
161	
162	        if (res.discount.compareTo(BigDecimal.ZERO) > 0) {
163	            receipt.append("Desconto: R$ ").append(formatCurrency(res.discount)).append("\n");
164	        }
165	
166	        receipt.append("Total: R$ ").append(formatCurrency(res.total)).append("\n");
167	
168	        return receipt.toString();
169	    }
170	
171	    public static String generateConfirmationEmail(Reservation res, String roomType) {
172	        StringBuilder email = new StringBuilder();
173	
174	        email.append("Olá, ").append(res.guestName).append("!\n\n");
175	        email.append("Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n");
176	        email.append(generateReceipt(res, roomType)).append("\n");
177	        email.append("A entrada é a partir das 14h, e a saída, até as 12h.\n");
178	        email.append("Até breve!\n");
179	
180	        return email.toString();
181	    }
182	
183	    private static String formatCurrency(BigDecimal value) {
184	        return String.format("%.2f", value).replace(".", ",");
185	    }
186	}
