268	    public static String generateOccupancyReport(LocalDate date) throws SQLException {
269	        StringBuilder csv = new StringBuilder();
270	        csv.append("room,type,reservation,check_in,check_out\n");
271	
272	        List<Integer> roomNumbers = getRoomNumbers();
273	        int occupiedCount = 0;
274	
275	        for (int roomNumber : roomNumbers) {
276	            List<Reservation> reservations = ReservationService.getReservationsByRoomAndDate(roomNumber, date);
277	
278	            if (!reservations.isEmpty()) {
279	                for (Reservation res : reservations) {
280	                    csv.append(res.roomNumber).append(",")
281	                       .append(getRoomType(roomNumber)).append(",")
282	                       .append(res.id).append(",")
283	                       .append(res.checkIn).append(",")
284	                       .append(res.checkOut).append("\n");
285	                }
286	                occupiedCount++;
287	            }
288	        }
289	
290	        csv.append("total,").append(occupiedCount).append("/5\n");
291	        return csv.toString();
292	    }
