294	    public static String generateRevenueReport(YearMonth month) throws SQLException {
295	        StringBuilder csv = new StringBuilder();
296	        csv.append("reservation,room,check_in,check_out,status,amount\n");
297	
298	        String sql = """
299	            SELECT r.id, rm.number, r.check_in, r.check_out, r.status,
300	                   r.amount_paid, r.refund, r.total
301	            FROM reservations r
302	            JOIN rooms rm ON r.room_id = rm.id
303	            WHERE EXTRACT(YEAR FROM r.check_in) = ? AND EXTRACT(MONTH FROM r.check_in) = ?
304	              AND (r.status IN ('CONFIRMED', 'CHECKED_IN', 'CHECKED_OUT') OR
305	                   (r.status = 'CANCELLED' AND r.amount_paid > 0))
306	            ORDER BY r.check_in, r.id
307	        """;
308	
309	        BigDecimal total = BigDecimal.ZERO;
310	
311	        try (Connection conn = Database.getConnection();
312	             PreparedStatement stmt = conn.prepareStatement(sql)) {
313	            stmt.setInt(1, month.getYear());
314	            stmt.setInt(2, month.getMonthValue());
315	            try (ResultSet rs = stmt.executeQuery()) {
316	                while (rs.next()) {
317	                    int reservationId = rs.getInt("id");
318	                    int roomNumber = rs.getInt("number");
319	                    LocalDate checkIn = rs.getObject("check_in", LocalDate.class);
320	                    LocalDate checkOut = rs.getObject("check_out", LocalDate.class);
321	                    String status = rs.getString("status");
322	                    BigDecimal amountPaid = rs.getBigDecimal("amount_paid");
323	                    BigDecimal refund = rs.getBigDecimal("refund");
324	
325	                    BigDecimal amount;
326	                    if (status.equals("CANCELLED")) {
327	                        amount = amountPaid;
328	                        if (refund != null && refund.compareTo(BigDecimal.ZERO) > 0) {
329	                            amount = amount.subtract(refund);
330	                        }
331	                    } else {
332	                        amount = amountPaid;
333	                        if (refund != null && refund.compareTo(BigDecimal.ZERO) > 0) {
334	                            amount = amount.subtract(refund);
335	                        }
336	                    }
337	
338	                    csv.append(reservationId).append(",")
339	                       .append(roomNumber).append(",")
340	                       .append(checkIn).append(",")
341	                       .append(checkOut).append(",")
342	                       .append(status).append(",")
343	                       .append(String.format("%.2f", amount)).append("\n");
344	
345	                    total = total.add(amount);
346	                }
347	            }
348	        }
349	
350	        csv.append("total,,,,").append(String.format("%.2f", total)).append("\n");
351	        return csv.toString();
352	    }
