    21	
    22	    @Test
    23	    public void testCorporateDiscountTecnosul() {
    24	        LocalDate checkIn = LocalDate.of(2027, 3, 10);
    25	        LocalDate checkOut = LocalDate.of(2027, 3, 12);
    26	        BigDecimal baseRate = new BigDecimal("389.90");
    27	
    28	        PricingService.PricingResult result = PricingService.calculatePrice(
    29	            checkIn, checkOut, baseRate, "CORPORATE", "TECNOSUL"
    30	        );
    31	
    32	        assertEquals(2, result.nights);
    33	        assertEquals(new BigDecimal("779.80"), result.subtotal);
    34	        assertEquals(new BigDecimal("93.58"), result.discount);
    35	        assertEquals(new BigDecimal("686.22"), result.total);
    36	    }
