    42	        BigDecimal baseRate = new BigDecimal("249.90");
    43	
    44	        PricingService.PricingResult result = PricingService.calculatePrice(
    45	            checkIn, checkOut, baseRate, "LONG_STAY", null
    46	        );
    47	
    48	        assertEquals(7, result.nights);
    49	        assertEquals(new BigDecimal("1749.30"), result.subtotal);
